import{_ as t,o as r,c as s,a2 as n}from"./chunks/framework.CqdVOxXJ.js";const o="/rakkii-cars-guide/screenshots/06-lane-2-insurance-claims-and-loa/01-loa-card.png",a="/rakkii-cars-guide/screenshots/06-lane-2-insurance-claims-and-loa/03-release-tab.png",i="/rakkii-cars-guide/screenshots/06-lane-2-insurance-claims-and-loa/02-split-invoices.png",b=JSON.parse('{"title":"6. Lane 2 — Insurance claims & LOA billing","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/06-lane-2-insurance-claims-and-loa.md","filePath":"chapters/06-lane-2-insurance-claims-and-loa.md","lastUpdated":1793268728000}'),l={name:"chapters/06-lane-2-insurance-claims-and-loa.md"};function h(d,e,u,g,c,p){return r(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="_6-lane-2-—-insurance-claims-loa-billing" tabindex="-1">6. Lane 2 — Insurance claims &amp; LOA billing <a class="header-anchor" href="#_6-lane-2-—-insurance-claims-loa-billing" aria-label="Permalink to &quot;6. Lane 2 — Insurance claims &amp; LOA billing&quot;">​</a></h1><p><strong>For:</strong> Shop Owner · <strong>Hubs:</strong> Workshop, Finance · <strong>Nature:</strong> Insurance · <strong>Job type:</strong> Insurance</p><p>An insurance job has two payers. The insurer pays what the <strong>Letter of Authorization (LOA)</strong> covers, usually 15–45 days after you bill. The customer pays their <strong>participation</strong> (deductible), plus any betterment, depreciation or extras, <strong>before</strong> the car leaves.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Insurer on file → Insurance job (Booked) → Quote → Waiting for LOA → LOA saved</span></span>\n<span class="line"><span>→ Mark authorized → Under repair → Surrendered parts → QC → Ready for pickup</span></span>\n<span class="line"><span>→ Bill insurer + Bill customer → Customer pays participation → Release → Insurer balance in Who owes us</span></span></code></pre></div><h2 id="_6-1-insurers-directory-workshop-insurers" tabindex="-1">6.1 Insurers directory (<code>/workshop/insurers</code>) <a class="header-anchor" href="#_6-1-insurers-directory-workshop-insurers" aria-label="Permalink to &quot;6.1 Insurers directory (`/workshop/insurers`)&quot;">​</a></h2><ol><li>Go to <strong>Workshop › Insurers</strong>.</li><li>Press <strong>Add insurer</strong> and fill <strong>Name</strong> (required), <strong>Days to pay</strong> (default 30), <strong>Terms days</strong> (optional; blank means no terms warning), <strong>Phone</strong> and <strong>Email</strong>.</li><li><strong>Save insurer</strong>. Use <strong>Rename</strong> to correct a name or change the insurer&#39;s terms.</li></ol><p><strong>Days to pay</strong> sets the expected pay date on insurer invoices, which drives ageing in <strong>Who owes us</strong>.</p><h2 id="_6-2-create-the-insurance-job" tabindex="-1">6.2 Create the insurance job <a class="header-anchor" href="#_6-2-create-the-insurance-job" aria-label="Permalink to &quot;6.2 Create the insurance job&quot;">​</a></h2><ol><li><strong>Workshop › New job</strong>.</li><li><strong>Job type</strong>: Insurance. <strong>Nature</strong>: Insurance.</li><li>Customer and vehicle as in <a href="/rakkii-cars-guide/chapters/05-lane-1-private-walk-in-jobs#_5-2-create-the-job-workshop-jobs-new">Chapter 5</a>.</li><li>In <strong>Insurance</strong>: choose the <strong>Insurer</strong> (required), and enter <strong>Claim number</strong>, <strong>Policy number</strong> and <strong>Adjuster</strong>.</li><li><strong>Create job</strong>. The job gets an <strong>Insurance</strong> tab with the claim timeline.</li></ol><p>Do the intake checklist and photos as usual — the adjuster will rely on them.</p><h2 id="_6-3-quote-for-the-adjuster" tabindex="-1">6.3 Quote for the adjuster <a class="header-anchor" href="#_6-3-quote-for-the-adjuster" aria-label="Permalink to &quot;6.3 Quote for the adjuster&quot;">​</a></h2><ol><li>Add <strong>Work lines</strong> on the <strong>Work</strong> tab. Set <strong>Who pays</strong> per line (see 6.7).</li><li><strong>Quote › Create quote</strong> and <strong>Print estimate</strong> for the adjuster&#39;s inspection.</li><li>Press <strong>Waiting for LOA</strong>. Status: <strong>Waiting for LOA</strong>. The banner says &quot;Mark authorized when the LOA is on file.&quot;</li></ol><h3 id="while-you-wait-for-the-loa" tabindex="-1">While you wait for the LOA <a class="header-anchor" href="#while-you-wait-for-the-loa" aria-label="Permalink to &quot;While you wait for the LOA&quot;">​</a></h3><p>On <strong>Waiting for LOA</strong> the job has these buttons:</p><table tabindex="0"><thead><tr><th>Button</th><th>When to use it</th></tr></thead><tbody><tr><td><strong>Mark authorized</strong></td><td>The LOA is saved (number and amount). Greyed out until then, with the reason &quot;Marking authorised requires an LOA number and amount.&quot;</td></tr><tr><td><strong>Start work (cash / no LOA)</strong></td><td>The customer will settle in cash, or the insurer confirmed another way. Asks for a reason, which is kept in the status log.</td></tr><tr><td><strong>Back to quote</strong></td><td>The adjuster wants the estimate changed.</td></tr><tr><td><strong>Put on hold</strong></td><td>The claim is stuck (asks for a reason).</td></tr><tr><td><strong>Cancel job</strong></td><td>The claim was denied and the customer will not proceed.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Do not start insurance work without an LOA</p><p>From Booked, For canvass, Quoted or Waiting for LOA the button reads <strong>Start work (no LOA)</strong> / <strong>Start work (cash / no LOA)</strong> and asks &quot;Insurance jobs should wait for an LOA. Write why this one does not.&quot; Use it only when the customer settles in cash or the insurer has confirmed in writing another way. A missing LOA only greys out <strong>Mark authorized</strong>; the cash start stays available.</p></div><h2 id="_6-4-record-the-loa" tabindex="-1">6.4 Record the LOA <a class="header-anchor" href="#_6-4-record-the-loa" aria-label="Permalink to &quot;6.4 Record the LOA&quot;">​</a></h2><p>When the insurer sends the LOA:</p><ol><li>Open the <strong>Insurance</strong> tab, card <strong>Letter of authorization</strong>.</li><li>Enter: <ul><li><strong>LOA number</strong></li><li><strong>LOA date</strong></li><li><strong>Authorized amount</strong></li><li><strong>Participation</strong> (customer deductible)</li><li><strong>Depreciation / Betterment</strong> — <strong>Depreciation</strong> and <strong>Betterment</strong> amounts</li><li><strong>Insurer expected pay date</strong></li></ul></li><li>Press <strong>Save LOA</strong>. The card shows &quot;LOA recorded — attach the letter on Files.&quot;</li><li>Go to <strong>Files</strong>, upload the LOA as a <strong>PDF</strong>, and leave <strong>Visible in the customer portal</strong> off.</li><li>Back on the Insurance tab, use <strong>Open LOA PDF</strong> to check it.</li></ol><p><strong>Who can see it:</strong> opening the LOA PDF needs the <strong>Can open LOA PDF</strong> permission; seeing LOA peso amounts needs <strong>Can see LOA pesos / job margin</strong> (<a href="/rakkii-cars-guide/chapters/13-admin-shop-settings-and-staff-permissions">Chapter 13</a>). Without them the screen shows &quot;LOA PDF permission required&quot;.</p><h3 id="hidden-damage-supplements" tabindex="-1">Hidden damage: supplements <a class="header-anchor" href="#hidden-damage-supplements" aria-label="Permalink to &quot;Hidden damage: supplements&quot;">​</a></h3><p>If the car needs more work after tear-down, quote it, get the insurer&#39;s approval, then under <strong>Supplements</strong> enter the <strong>Extra amount</strong> and <strong>Extra LOA number</strong> and press <strong>Add supplement</strong>.</p><p><img src="'+o+'" alt="Letter of authorization card with LOA number, date, amounts"></p><h2 id="_6-5-mark-authorized-to-unlock-repair" tabindex="-1">6.5 Mark authorized to unlock repair <a class="header-anchor" href="#_6-5-mark-authorized-to-unlock-repair" aria-label="Permalink to &quot;6.5 Mark authorized to unlock repair&quot;">​</a></h2><ol><li>Check <strong>Claim status → What is blocking</strong> on the Insurance tab. Every item should show ✓.</li><li>Press <strong>Mark authorized</strong>. The app requires the <strong>LOA number and amount</strong> (&quot;Marking authorised requires an LOA number and amount.&quot;). Status: <strong>Authorized</strong>.</li><li>Assign the technician and press <strong>Start work</strong>. Status: <strong>Under repair</strong>.</li></ol><p>From <strong>Authorized</strong> you can also choose <strong>Waiting for parts</strong> or <strong>Put on hold</strong>.</p><h2 id="_6-6-surrendered-parts" tabindex="-1">6.6 Surrendered parts <a class="header-anchor" href="#_6-6-surrendered-parts" aria-label="Permalink to &quot;6.6 Surrendered parts&quot;">​</a></h2><p>Insurers usually take back the replaced damaged parts.</p><ol><li>On the <strong>Insurance</strong> tab (or the technician on <strong>Work</strong>), card <strong>Surrendered Parts</strong>, press <strong>Add part</strong>.</li><li>Fill <strong>Description</strong>, <strong>Qty</strong>, <strong>Surrender date</strong>, <strong>Received by</strong>, <strong>Note</strong>. <strong>Save</strong>.</li><li>If nothing goes back, tick <strong>No parts to surrender</strong>.</li></ol><p>Until then the job shows &quot;No surrendered parts logged.&quot;</p><h2 id="_6-7-split-the-lines-who-pays" tabindex="-1">6.7 Split the lines: Who pays <a class="header-anchor" href="#_6-7-split-the-lines-who-pays" aria-label="Permalink to &quot;6.7 Split the lines: Who pays&quot;">​</a></h2><p>Every work line has <strong>Who pays</strong>:</p><ul><li><strong>Insurer</strong> — work covered by the LOA.</li><li><strong>Customer</strong> — owner extras the customer asked for (for example a full repaint instead of a panel).</li></ul><p>Participation, depreciation and betterment come from the LOA. The owner decides how they are billed in <strong>Admin › Shop settings › Workshop rules › Quality check</strong>:</p><table tabindex="0"><thead><tr><th>Switch</th><th>Off (default)</th><th>On</th></tr></thead><tbody><tr><td><strong>Participation and betterment reduce insurer share</strong></td><td>Billed on top to the customer; insurer share unchanged</td><td>Moved from the insurer share to the customer before invoices post</td></tr><tr><td><strong>Depreciation reduces insurer share</strong></td><td>Same as above, for depreciation</td><td>Moved from the insurer share to the customer</td></tr></tbody></table><p><strong>Example:</strong> total repair PHP 85,000, LOA PHP 80,000, participation PHP 5,000, owner extras PHP 3,500. The insurer invoice is PHP 80,000 (expected about 30 days later). The customer pays participation and extras before release.</p><h2 id="_6-8-bill-insurer-and-bill-customer" tabindex="-1">6.8 Bill insurer and Bill customer <a class="header-anchor" href="#_6-8-bill-insurer-and-bill-customer" aria-label="Permalink to &quot;6.8 Bill insurer and Bill customer&quot;">​</a></h2><ol><li>When the car is ready, open <strong>Pay › Invoices</strong>.</li><li>Press <strong>Bill insurer ₱…</strong> — a posted <strong>Insurer invoice</strong> with the insurer&#39;s expected pay date.</li><li>Press <strong>Bill customer ₱…</strong> — a posted <strong>Customer invoice</strong> for participation and customer lines.</li><li><strong>Print insurer invoice</strong> and <strong>Print customer invoice</strong>.</li></ol><p>The Pay tab shows <strong>Customer owes</strong> and <strong>Insurer owes</strong> separately, plus <strong>Expected withholding</strong> and <strong>Expected net</strong> when an insurance withholding percent is set.</p><h2 id="_6-9-collect-the-customer-share-and-release" tabindex="-1">6.9 Collect the customer share and release <a class="header-anchor" href="#_6-9-collect-the-customer-share-and-release" aria-label="Permalink to &quot;6.9 Collect the customer share and release&quot;">​</a></h2><ol><li><strong>Record a payment</strong> with <strong>Who paid</strong>: Customer for the participation. The customer and insurer shares must be recorded as separate payments.</li><li>The car is held until <strong>Customer owes</strong> is PHP 0.00 (shop default). It is <strong>not</strong> held for the insurer (default off) — the insurer balance stays open and appears in <strong>Finance › Who owes us</strong> (<a href="/rakkii-cars-guide/chapters/08-lane-4-billing-chain-receivables-storage-credit-notes">Chapter 8</a>).</li><li>The LOA must be on file: &quot;LOA must be on file before releasing an insurance job.&quot;</li><li>Complete the release checks and press <strong>Release car</strong> (see <a href="/rakkii-cars-guide/chapters/05-lane-1-private-walk-in-jobs#_5-10-release-checklist-gate-pass-and-acceptance">Chapter 5</a>).</li></ol><p>If a job is set to <strong>Wait for the insurer</strong>, release is blocked until the insurer pays: &quot;This job holds the vehicle until the insurer pays.&quot; Only an owner override passes it.</p><h2 id="_6-10-print-the-release-of-claim" tabindex="-1">6.10 Print the Release of Claim <a class="header-anchor" href="#_6-10-print-the-release-of-claim" aria-label="Permalink to &quot;6.10 Print the Release of Claim&quot;">​</a></h2><ol><li>On the <strong>Release</strong> tab (also on <strong>Pay</strong> and the Work tab print list) press <strong>Release of Claim</strong>.</li><li>The paper fills in the insured, insurer, claim and policy numbers, plate, vehicle and LOA number. The wording comes from <strong>Admin › Shop settings › Workshop rules › Insurance release of claim</strong>. Owners and admins print the same shop wording; if the shop has not set any, the default wording is used.</li><li>Have the customer sign it; send it to the insurer with the insurer invoice.</li></ol><p><img src="'+a+'" alt="Release tab of an insurance job with Release of Claim, Print gate pass and Print customer invoice"></p><p>When the insurer pays, record it on the job with <strong>Who paid</strong>: Insurer and <strong>Apply to invoice</strong> = the insurer invoice. Then <strong>Close job</strong>.</p><p><img src="'+i+'" alt="Pay tab showing a posted insurer invoice and customer invoice"></p>',47)])])}const f=t(l,[["render",h]]);export{b as __pageData,f as default};
